text:
&.busy {
  cursor: wait;
}

#loadingOverlay {
  display: none;
  opacity: 0;
}

&.spinner #loadingOverlay {
  display: grid;
  position: absolute;
  inset: 0;
  place-items: center;
  background-color: var(--hub-loader-background);
  opacity: 0.8;
  z-index: 2;
  border-radius: inherit;

  @media (prefers-reduced-motion: no-preference) {
    animation: 0.5s linear 0s hub-reveal-loader;
  }
}
